#!/usr/bin/env bash
# Generated by Antigravity CLI 1.4.2 (Gemini 3.8 Flash (High))
#
# scripts/package-windows.sh - Cross-compile and package Neverball for Windows
#
# Cross-compiles Neverball, Neverputt, and mapc for Windows using MinGW-w64,
# bundles runtime DLLs, packages game data into base-neverball.zip, and
# creates a standalone ZIP distribution archive.

set -euo pipefail

# -----------------------------------------------------------------------------
# Configuration and Defaults
# -----------------------------------------------------------------------------

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"

ARCH="win64"
BUILD_TYPE="release"
OUT_DIR="build/windows"
SKIP_BUILD=0

usage() {
    cat <<EOF
Usage: $(basename "$0") [options]

Cross-compiles and packages Neverball for Windows using MinGW-w64.

Options:
  --arch <arch>         Target architecture: win64 (default) or win32
  --build-type <type>   Build configuration: release (default) or devel
  --out-dir <dir>       Output directory for release ZIP (default: build/windows)
  --skip-build          Skip compilation and assemble package from existing binaries
  -h, --help            Show this help message
EOF
    exit 0
}

# Parse command line options
while [[ $# -gt 0 ]]; do
    case "$1" in
        --arch)
            ARCH="$2"
            shift 2
            ;;
        --build-type)
            BUILD_TYPE="$2"
            shift 2
            ;;
        --out-dir)
            OUT_DIR="$2"
            shift 2
            ;;
        --skip-build)
            SKIP_BUILD=1
            shift
            ;;
        -h|--help)
            usage
            ;;
        *)
            echo "Error: Unknown option: $1" >&2
            echo "Run '$(basename "$0") --help' for usage." >&2
            exit 1
            ;;
    esac
done

mkdir -p "$OUT_DIR"
OUT_DIR="$(cd "$OUT_DIR" && pwd)"

# -----------------------------------------------------------------------------
# Target Architecture & Toolchain Setup
# -----------------------------------------------------------------------------

case "$ARCH" in
    win64|x86_64|x64|64bit)
        ARCH_LABEL="win64"
        TRIPLE="x86_64-w64-mingw32"
        ;;
    win32|i686|x86|32bit)
        ARCH_LABEL="win32"
        TRIPLE="i686-w64-mingw32"
        ;;
    *)
        echo "Error: Unsupported architecture '$ARCH'. Supported: win64, win32." >&2
        exit 1
        ;;
esac

# Check for Fedora wrapper or fallback to standard cross tools
if [[ "$ARCH_LABEL" == "win64" ]] && command -v mingw64-make >/dev/null 2>&1; then
    MAKE_CMD="mingw64-make"
elif [[ "$ARCH_LABEL" == "win32" ]] && command -v mingw32-make >/dev/null 2>&1; then
    MAKE_CMD="mingw32-make"
elif command -v make >/dev/null 2>&1; then
    MAKE_CMD="make CC=${TRIPLE}-gcc CXX=${TRIPLE}-g++ WINDRES=${TRIPLE}-windres PKG_CONFIG=${TRIPLE}-pkg-config"
else
    echo "Error: No suitable make command found for ${TRIPLE}." >&2
    exit 1
fi

# Locate MinGW sysroot DLL directory
SYSROOT_BIN="/usr/${TRIPLE}/sys-root/mingw/bin"
if [[ ! -d "$SYSROOT_BIN" ]]; then
    for cand in "/usr/${TRIPLE}/bin" "/mingw64/bin" "/mingw32/bin" "/ucrt64/bin"; do
        if [[ -d "$cand" ]]; then
            SYSROOT_BIN="$cand"
            break
        fi
    done
fi

OBJDUMP_CMD="${TRIPLE}-objdump"
if ! command -v "$OBJDUMP_CMD" >/dev/null 2>&1; then
    OBJDUMP_CMD="objdump"
fi

for cmd in make python3 zip; do
    if ! command -v "$cmd" >/dev/null 2>&1; then
        echo "Error: Required command '$cmd' is not found in PATH." >&2
        exit 1
    fi
done

VERSION="$(sh "$REPO_ROOT/scripts/version.sh")"
echo "=== Packaging Neverball ${VERSION} (${ARCH_LABEL}) ==="

# -----------------------------------------------------------------------------
# Compilation (Host Data + MinGW Executables)
# -----------------------------------------------------------------------------

NCPU="$(nproc 2>/dev/null || sysctl -n hw.ncpu 2>/dev/null || echo 4)"

if [[ "$SKIP_BUILD" -eq 0 ]]; then
    echo "==> Step 1: Compiling host mapc, sols, locales, and desktop files..."
    make clean-src
    make -j"$NCPU" sols locales desktops

    echo "==> Step 2: Cross-compiling Neverball Windows binaries (${ARCH_LABEL})..."
    make clean-src
    $MAKE_CMD -j"$NCPU" \
        -o sols -o locales -o desktops \
        BUILD="$BUILD_TYPE" \
        PLATFORM=mingw \
        neverball.exe neverputt.exe mapc.exe
fi

# Verify Windows executables exist
for bin in neverball.exe neverputt.exe mapc.exe; do
    if [[ ! -f "$REPO_ROOT/$bin" ]]; then
        echo "Error: Expected compiled binary '$bin' was not found." >&2
        exit 1
    fi
done

# -----------------------------------------------------------------------------
# Assemble Distribution Staging Directory
# -----------------------------------------------------------------------------

STAGE_NAME="Neverball-${VERSION}-${ARCH_LABEL}"
STAGE_DIR="$OUT_DIR/$STAGE_NAME"

echo "==> Step 3: Assembling distribution directory at ${STAGE_DIR}..."
rm -rf "$STAGE_DIR"
mkdir -p "$STAGE_DIR/data" "$STAGE_DIR/locale"

# 1. Copy executables
cp "$REPO_ROOT/neverball.exe" "$STAGE_DIR/"
cp "$REPO_ROOT/neverputt.exe" "$STAGE_DIR/"
cp "$REPO_ROOT/mapc.exe" "$STAGE_DIR/"
chmod 755 "$STAGE_DIR"/*.exe

# 2. Package game data into base-neverball.zip
DATA_ZIP="$STAGE_DIR/data/base-neverball.zip"
echo "==> Packaging game data into ${DATA_ZIP}..."
(
    cd "$REPO_ROOT/data"
    zip -r -q "$DATA_ZIP" . \
        -x "*.autosave.map" "*.zip" "*.pk3" ".DS_Store" "*/.DS_Store"
)

# 3. Copy locale catalogs
if [[ -d "$REPO_ROOT/locale" ]]; then
    echo "==> Copying localization catalogs..."
    cp -R "$REPO_ROOT/locale"/* "$STAGE_DIR/locale/" 2>/dev/null || true
fi

# 4. Copy documentation and licenses
for docfile in README.md LICENSE.md; do
    if [[ -f "$REPO_ROOT/$docfile" ]]; then
        cp "$REPO_ROOT/$docfile" "$STAGE_DIR/"
    fi
done

# 5. Copy level editor gamepacks (TrenchBroom and Radiant)
for tool_dir in TrenchBroom Radiant; do
    if [[ -d "$REPO_ROOT/$tool_dir" ]]; then
        echo "==> Copying $tool_dir gamepack..."
        cp -R "$REPO_ROOT/$tool_dir" "$STAGE_DIR/"
        find "$STAGE_DIR/$tool_dir" -name ".DS_Store" -delete 2>/dev/null || true
    fi
done

# -----------------------------------------------------------------------------
# Bundle Runtime DLLs
# -----------------------------------------------------------------------------

echo "==> Step 4: Resolving and bundling runtime DLLs..."
if [[ -d "$SYSROOT_BIN" ]]; then
    python3 "$REPO_ROOT/scripts/bundle-dlls.py" \
        --sysroot-bin "$SYSROOT_BIN" \
        --dest-dir "$STAGE_DIR" \
        --objdump "$OBJDUMP_CMD" \
        "$STAGE_DIR/neverball.exe" \
        "$STAGE_DIR/neverputt.exe" \
        "$STAGE_DIR/mapc.exe"
else
    echo "Warning: MinGW sysroot bin directory not found. Skipping DLL bundling." >&2
fi

# -----------------------------------------------------------------------------
# Create Release ZIP Archive
# -----------------------------------------------------------------------------

ZIP_NAME="Neverball-${VERSION}-${ARCH_LABEL}.zip"
ZIP_PATH="$OUT_DIR/$ZIP_NAME"

echo "==> Step 5: Creating release ZIP archive at ${ZIP_PATH}..."
rm -f "$ZIP_PATH"
(cd "$OUT_DIR" && zip -r -q "$ZIP_NAME" "$STAGE_NAME")

echo "=== Windows packaging complete! ==="
echo "Directory: ${STAGE_DIR}"
echo "Archive:   ${ZIP_PATH}"
